async function irAPagina(numero) {
  const url = new URL(location);
  url.searchParams.set('page', numero);
  history.pushState({}, '', url);

  const r = await fetch(`/api/productos?page=${numero}&size=20`);
  pintarLista(await r.json());
}

let siguiente = '/api/productos?limit=20';
let cargando = false;

const observer = new IntersectionObserver(async ([entrada]) => {
  if (!entrada.isIntersecting || cargando || !siguiente) return;
  cargando = true;
  const doc = await (await fetch(siguiente)).json();
  agregarTarjetas(doc.data);
  siguiente = doc.links.next;
  if (!siguiente) observer.disconnect();
  cargando = false;
});

observer.observe(document.querySelector('#centinela'));

paginas.texto:
**Paginación** cuando…
• el usuario **busca** algo concreto o compara resultados (tiendas con filtros, tablas, administración);
• necesita volver a una posición o compartirla;
• el pie de página contiene enlaces importantes.

**Scroll infinito** cuando…
• el objetivo es **explorar** un flujo sin un final claro (fotos, noticias, publicaciones);
• se usa sobre todo en móvil;
• el orden es cronológico o por relevancia y no importa la posición exacta.
